@Component
@RequiredArgsConstructor
class ParametrosArt61Tasklet implements Tasklet {

    private final ControlPasoRepository b00;      // S500B00CTRLPASO (solo lectura)
    private final P315Properties props;

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        ControlPaso cp = b00.find()
                .orElseThrow(() -> new ProcesoAbortadoException("NO EXISTE B00 EN BASE")); // DMTERMINATE

        BigDecimal tope = cp.importe300Smdf();                                 // 9(10)V99
        if (tope == null || tope.signum() <= 0) {
            // El fuente compila 20187.00 como respaldo (línea 953).
            tope = props.tope300SalariosRespaldo();
            log.warn("B00-IMP-300SMDF en cero; se usa el respaldo {}", tope);
        }
        var ec = ctx.getStepContext().getStepExecution().getJobExecution().getExecutionContext();
        ec.put("fechaTraspasoBenef", cp.fechaArt61());                          // B00-FECH-ART61
        ec.put("tope300Salarios", tope);
        return RepeatStatus.FINISHED;
    }
}

