@Component
@RequiredArgsConstructor
class CalendarioArt61 {

    private final CalendarioBancario calendario;   // reemplaza LOCSUP funciones 6, 8 y 18

    /** 20000411 + 20000412: primer viernes del año siguiente que sea día hábil. */
    LocalDate primerViernesHabilDelSiguienteAnio(LocalDate fechaProceso) {
        LocalDate f = LocalDate.of(fechaProceso.getYear() + 1, 1, 1)
                .with(TemporalAdjusters.nextOrSame(DayOfWeek.FRIDAY));   // LOCSUP fn 6 = 5 (viernes)
        while (!calendario.esDiaHabil(f)) {                              // LOCSUP fn 18 = 1 (hábil)
            f = f.plusWeeks(1);                                          // ADD 7 TO WS-DD-1ER-VIE
        }
        return f;
    }

    /** LOCSUP función 8 con 0090: fecha Art. 61 de B00 más 90 días. */
    Optional<LocalDate> limiteTraspaso(LocalDate fechaArt61) {
        return Optional.ofNullable(fechaArt61).map(f -> f.plusDays(90));
    }
}

@Bean
JpaPagingItemReader<Movimiento> movimientosDelMes(EntityManagerFactory emf,
        @Value("#{jobExecutionContext['fechaProceso']}") LocalDate fechaProceso) {
    LocalDate desde = fechaProceso.withDayOfMonth(1);           // MOVE 01 TO WS-PASO-DD
    return new JpaPagingItemReaderBuilder<Movimiento>()
            .name("movimientosDelMes")
            .entityManagerFactory(emf)
            .queryString("""
                select m from Movimiento m
                 where m.status <> 1                            -- B04-STATUS-MOVTO = 1 se omite
                   and m.fechaMovto >= :desde
                 order by m.fechaMovto, m.contrato
                """)
            .parameterValues(Map.of("desde", desde))
            .pageSize(1000)
            .build();
}

