public enum DestinoContrato { GERENCIA_Y_CAPITALIZACION, CANCELADO_SIN_MOV, CANCELADO_Y_SALDO_CERO, ART61 }

@Component
@RequiredArgsConstructor
class SelectorContratos implements ItemProcessor<Contrato, ContratoClasificado> {

    private final P315Properties props;   // producto-ahorro: 500, instrumento-ahorro: 6

    @Override
    public ContratoClasificado process(Contrato c) {
        var destinos = EnumSet.noneOf(DestinoContrato.class);

        if (c.producto() == props.productoAhorro() && c.instrumento() == props.instrumentoAhorro()) {
            if (c.status() != 2) {                                     // 2 = cancelado
                destinos.add(DestinoContrato.GERENCIA_Y_CAPITALIZACION); // INV-INDCAN 0, CANCELO 0
            }
        } else if (c.staCancel() > 0 && !c.migradoS111()) {
            if (Set.of(0, 1, 5).contains(c.status())) {
                destinos.add(DestinoContrato.CANCELADO_SIN_MOV);           // INV-CANCELO-S = 1
            } else if (c.status() == 4 && c.saldoActual().signum() == 0) {
                destinos.add(DestinoContrato.CANCELADO_Y_SALDO_CERO);      // INV-CANCELO-S = 2
            }
        }
        // Independiente de lo anterior: contratos vigentes en beneficencia.
        if (Set.of(0, 1, 5).contains(c.status()) && Set.of(3, 6, 7, 8).contains(c.staBenef())) {
            destinos.add(DestinoContrato.ART61);
        }
        return destinos.isEmpty() ? null : new ContratoClasificado(c, destinos);
    }
}

/** WS-ART-REG: contrato en Artículo 61 (tipo 03). */
public record RegistroArt61(
        int producto, int instrumento, int moneda,
        String contrato, String cliente,          // 9(12) como String
        int sucursalPromotora, int tipoPersona, int status, int sector, int indLineaCredito,
        BigDecimal saldo,                         // 9(12)V99: saldo actual + protegido o bloqueado
        BigDecimal saldoCongelado,                // B03-SDO-CONGBENE
        LocalDate fecUltMov, LocalDate fecCliente, LocalDate fecApertura,
        String nombre,
        SituacionArt61 situacion,                 // WS-ART-STBENF + WS-ART-LEYBENF
        String fechaArt61,                        // X(08): se copia tal cual de B03-FECH-BENEF
        Optional<LocalDate> fechaTraspaso) {}     // vacío = espacios en WS-ART-FTRSBEN-X

/** WKS-TAB-ART61, indexada por WS-ART-STBENF. */
public enum SituacionArt61 {
    DENTRO(1, "DENTRO DE ART.61"),
    ENTRADA(2, "ENTRADA ART.61"),
    ENTRADA_POR_DESBLOQUEO(3, "ENTRADA ART.61 X DES-BLOQ"),
    SALIDA_POR_REACTIVACION(4, "SALIDA ART.61 REACTIVACION"),
    SALIDA_POR_BLOQUEO(5, "SALIDA ART.61 X BLOQUEO"),
    CON_SALDO_MAYOR_300(6, "EN ART.61 C/SDO>300 SMVDF");   // definida, nunca asignada
    final int codigo; final String leyenda;
    SituacionArt61(int c, String l) { codigo = c; leyenda = l; }
}

@Component
class ClasificadorArt61 {

    /** 52112300-LLENO-ART61: estatus de beneficencia de B03 a situación del archivo. */
    SituacionArt61 situacion(Contrato c, LocalDate fechaProceso) {
        return switch (c.staBenef()) {
            case 7 -> SituacionArt61.SALIDA_POR_BLOQUEO;
            case 6 -> SituacionArt61.SALIDA_POR_REACTIVACION;
            case 8 -> SituacionArt61.ENTRADA_POR_DESBLOQUEO;
            default -> YearMonth.from(c.fechaBenef()).equals(YearMonth.from(fechaProceso))
                    ? SituacionArt61.ENTRADA     // entró en el mes de proceso
                    : SituacionArt61.DENTRO;     // ya estaba en Artículo 61
        };
    }

    /** W77-SDO-TOT = B03-SDO-ACTUAL + B03-SDOPROT-BLOQ. */
    BigDecimal saldoTotal(Contrato c) {
        return c.saldoActual().add(c.saldoProtegidoBloqueado());   // suma exacta, escala 2
    }
}

/** Solo situaciones 1 a 3, plazo cumplido, saldo dentro del tope y mismo año que el límite. */
Optional<LocalDate> fechaTraspaso(Contrato c, SituacionArt61 s, BigDecimal saldoTotal,
                                  LocalDate limite90, BigDecimal tope300,
                                  LocalDate primerViernesHabil) {
    if (s.codigo >= 4) return Optional.empty();                    // salidas no se traspasan
    if (c.fechaBenef().isAfter(limite90)) return Optional.empty(); // aún no cumple el plazo
    if (saldoTotal.compareTo(tope300) > 0) return Optional.empty(); // excede 300 salarios
    if (c.fechaBenef().getYear() != limite90.getYear()) return Optional.empty();
    return Optional.of(primerViernesHabil);                        // WS-FEC-1ER-VIE
}

/** 52211460-VALIND: encabezado de tipo de cancelación al cambiar indicador o tipo. */
private boolean primeraVez = true;
private Integer indCanAnterior, canceloAnterior;

void imprime(LineaCancelado l, ReporteCancelados r) {
    if (primeraVez) {
        r.encabezadoTipo(l);                  // WS-CAN-TIPCAN + WS-TIT-CAN
        primeraVez = false;
    }
    // En el fuente, ADD 4 TO WS-LINEA1 y MOVE 1 TO WS-9VEZ quedan fuera del IF por el punto
    // de la línea 1943: el contador de líneas suma 4 en cada detalle. Se conserva como opción.
    if (props.replicarContadorLineasOriginal()) {
        r.sumaLineas(4);
    }
    boolean cambio = !Objects.equals(l.indCan(), indCanAnterior)
                  || !Objects.equals(l.cancelo(), canceloAnterior);
    if (cambio) {
        r.blancos(2);
        r.encabezadoTipo(l);
    }
    r.detalle(l);
    indCanAnterior = l.indCan();
    canceloAnterior = l.cancelo();
}
